{
  "predictors": [
    {
      "name": "Digital Engagement Index",
      "construction": "Constructed by measuring the frequency of updates and user engagement metrics on company websites and official social media channels over the past year.",
      "rationale": "Firms with higher digital engagement may signal proactive communication strategies and stronger brand presence, potentially leading to better sales prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Sustainability Report Frequency",
      "construction": "Count the number of sustainability reports issued by a company in the past three years.",
      "rationale": "Frequent sustainability reporting may indicate a company's focus on long-term strategic planning and risk management, appealing to socially responsible investors.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "CEO Media Sentiment",
      "construction": "Analyze sentiment in media articles mentioning the CEO over the past six months using NLP sentiment analysis tools.",
      "rationale": "Positive media sentiment regarding the CEO could reflect confidence in leadership, potentially leading to better firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Review Sentiment",
      "construction": "Aggregate sentiment scores from online employee reviews on platforms like Glassdoor over the past year.",
      "rationale": "Positive employee sentiment could indicate high morale and productivity, potentially translating into superior firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "R&D Project Launches",
      "construction": "Count the number of R&D projects or product launches announced by the firm over the past two years.",
      "rationale": "Firms with frequent product innovations may capture market share and generate higher future cash flows.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Calculate the proportion of diverse members (gender, ethnicity) on the firm's board relative to industry averages.",
      "rationale": "Greater board diversity might enhance decision-making processes and better reflect diverse market needs, potentially improving firm performance.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Acquisition Cost Efficiency",
      "construction": "Divide the total marketing and sales expenses by the number of new customers acquired over the past year.",
      "rationale": "Efficient customer acquisition may signal effective marketing strategies and cost management, leading to improved profitability.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Industry Disruption Index",
      "construction": "Identify and score firms based on the percentage of revenue derived from newly developed technologies or services over the past three years.",
      "rationale": "High revenue from new technologies may indicate a company’s ability to adapt and lead in disruptive markets, potentially enhancing growth prospects.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Patent Citation Impact",
      "construction": "Calculate the average number of citations received by a firm's patents over the past five years.",
      "rationale": "Highly-cited patents may signal valuable innovations and strong competitive advantages, potentially leading to superior market position.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Word-of-Mouth Activity",
      "construction": "Track the frequency and sentiment of consumer discussions about the firm's products on online platforms over the past six months.",
      "rationale": "High levels of positive word-of-mouth can drive consumer interest and sales growth, enhancing firm valuation.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
